    /**
     * Ensures cached data populates the security context.
     */
    public function testVerifyAuthUsesCachedData(): void
    {
        /*
         * Arrange: seed the cache with the verified claims of the token.
         */
        $cache = new ArrayCache([
            JwtVerifierMiddleware::CACHE_PREFIX . 'token' => $this->cachedClaimsJson()
        ]);

        $context = $this->createMock(Context::class);
        $context->expects($this->once())
            ->method('setSecurityContext')
            ->with($this->isInstanceOf(\Civi\Lughauth\Shared\Security\Connection::class), $this->isInstanceOf(Identity::class));

        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $context);

        /*
         * Act: handle the request with cached identity data.
         */
        $response = $middleware($this->request('Bearer token'), $this->handler());

        /*
         * Assert: verify the request succeeds.
         */
        $this->assertSame(200, $response->getStatusCode());
    }

    /**
     * The acr and auth_time of the token reach the authentication context, so the logic can ask
     * for a step-up (task 067); amr is the RFC 8176 list issued by this server.
     */
    public function testTheAuthenticationClaimsReachTheContext(): void
    {
        $authTime = time() - 120;
        $cache = new ArrayCache([
            JwtVerifierMiddleware::CACHE_PREFIX . 'token' => json_encode(['claims' => [
                ...$this->claims(),
                'acr' => 'urn:lugh:acr:mfa',
                'amr' => ['pwd', 'otp', 'mfa'],
                'auth_time' => $authTime,
            ]]),
        ]);
        $authentication = null;
        $context = $this->createMock(Context::class);
        $context->method('setSecurityContext')->willReturnCallback(function ($connection, $identity, $auth) use (&$authentication): void {
            $authentication = $auth;
        });

        $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $context)($this->request('Bearer token'), $this->handler());

        $this->assertSame(
            ['urn:lugh:acr:mfa', 'pwd otp mfa', true, $authTime],
            [$authentication->getAcr(), $authentication->getAuthenticationMethod(), $authentication->isMfa(), $authentication->getAuthenticatedAt()->getTimestamp()]
        );
        $this->assertTrue($authentication->satisfies(\Civi\Lughauth\Shared\Security\Acr::MULTI_FACTOR, 300));
        $this->assertFalse($authentication->satisfies(\Civi\Lughauth\Shared\Security\Acr::MULTI_FACTOR, 60));
    }

    /**
     * Ensures authorization is read from cookies for GET requests.
     */
    public function testVerifyAuthReadsCookieAuthorization(): void
    {
        /*
         * Arrange: seed cache with cookie token identity data.
         */
        $token = 'cookie-token';
        $cache = new ArrayCache([
            JwtVerifierMiddleware::CACHE_PREFIX . $token => $this->cachedClaimsJson()
        ]);
        $context = $this->createMock(Context::class);
        $context->expects($this->never())
            ->method('setSecurityContext');
        $client = $this->createMock(ClientInterface::class);
        $client->expects($this->never())->method('sendRequest');
        $middleware = $this->middleware(['security.jwt.verify.publickey.location' => 'http://jwks'], $cache, $context, $client);

        $prevCookie = $_COOKIE;
        $prevGet = $_GET;
        $_COOKIE['Authorization'] = $token;
        unset($_GET['Authorization']);

        try {
            /*
             * Act: handle the request with cookie authorization.
             */
            $response = $middleware($this->request(''), $this->handler());
        } finally {
            $_COOKIE = $prevCookie;
            $_GET = $prevGet;
        }

        /*
         * Assert: verify the request succeeds using cookie auth.
         */
        $this->assertSame(200, $response->getStatusCode());
    }

