    /**
     * Ensures extractRoles skips empty path segments from a leading slash.
     */
    public function testExtractRolesSkipsEmptySegments(): void
    {
        /*
         * Arrange: configure a leading-slash roles path that yields empty segments.
         */
        $middleware = $this->middleware(['security.jwt.verify.path.roles' => '/realm_access/roles']);
        $method = new ReflectionMethod($middleware, 'extractRoles');

        /*
         * Act: invoke extractRoles with a matching payload.
         */
        $result = $method->invoke($middleware, (object) ['realm_access' => (object) ['roles' => ['admin', 'user']]]);

        /*
         * Assert: verify roles are correctly extracted despite the leading slash.
         */
        $this->assertSame(['admin', 'user'], $result);
    }

    private function middleware(
        array $configOverrides = [],
        ?CacheInterface $cache = null,
        ?Context $context = null,
        ?ClientInterface $client = null,
        ?MagicLinkService $magicLinkService = null,
        ?RequestFactoryInterface $requestFactory = null,
    ): JwtVerifierMiddleware {
        $config = new class ($configOverrides) extends AppConfig {
            public function __construct(private readonly array $overrides)
            {
                $this->develop = true;
                $this->name = 'app';
                $this->managementEndpoint = '/management';
            }

            public function get(string $name, mixed $def = null): mixed
            {
                return $this->overrides[$name] ?? $def;
            }
        };

        $context = $context ?? $this->createMock(Context::class);
        $cache = $cache ?? new ArrayCache();
        if ($requestFactory === null) {
            $requestFactory = $this->createMock(RequestFactoryInterface::class);
            $request = $this->createMock(\Psr\Http\Message\RequestInterface::class);
            $request->method('withHeader')->willReturnSelf();
            $requestFactory->method('createRequest')->willReturn($request);
        }
        $client = $client ?? $this->createMock(ClientInterface::class);
        $magicLinkService = $magicLinkService ?? $this->createMock(MagicLinkService::class);

        return new JwtVerifierMiddleware($config, $context, $cache, $requestFactory, $client, $magicLinkService, new \Slim\Psr7\Factory\StreamFactory());
    }

    /** @return array<string, mixed> claims of a valid access token of the `main` tenant */
    private function claims(): array
    {
        return ['sub' => 'user', 'iss' => self::ISSUER, 'aud' => ['client', 'app'], 'azp' => 'client', 'tenant' => 'main', 'jti' => 'jti-1', 'nbf' => time() - 10, 'exp' => time() + 1000];
    }

    private function request(string $authorization): ServerRequestInterface
    {
        $request = $this->createMock(ServerRequestInterface::class);
        $request->method('getHeader')->willReturn([$authorization]);
        $request->method('getMethod')->willReturn('GET');
        return $request;
    }

    private function handler(): \Psr\Http\Server\RequestHandlerInterface
    {
        return new class () implements \Psr\Http\Server\RequestHandlerInterface {
            public function handle(ServerRequestInterface $request): \Psr\Http\Message\ResponseInterface
            {
                return new \Slim\Psr7\Response(200);
            }
        };
    }

    private function jwt(array $payload, $key, ?string $typ = 'at+jwt', bool $withKid = true): string
    {
        $header = ['alg' => 'RS256'];
        if ($withKid) {
            $header['kid'] = $key->get('kid');
        }
        if ($typ !== null) {
            $header['typ'] = $typ;
        }
        $jwsBuilder = new JWSBuilder(new AlgorithmManager([new RS256()]));
        $jws = $jwsBuilder
            ->create()
            ->withPayload(json_encode($payload, JSON_THROW_ON_ERROR))
            ->addSignature($key, $header)
            ->build();

        return (new CompactSerializer())->serialize($jws, 0);
    }

    private function cachedClaimsJson(): string
    {
        return json_encode(['claims' => $this->claims()]);
    }

    private function stream(string $contents): \Psr\Http\Message\StreamInterface
    {
        return (new \Slim\Psr7\Factory\StreamFactory())->createStream($contents);
    }
}

/**
 * In-memory cache for middleware tests.
 */
final class ArrayCache implements CacheInterface
{
    public function __construct(
        /** @var array<string, mixed> Cached values. */
        private array $values = []
    ) {
    }

    public function get(string $key, mixed $default = null): mixed
    {
        return $this->values[$key] ?? $default;
    }

    /** @var array<string, null|int|DateInterval> TTL of each value, as it was set. */
    private array $ttls = [];

    public function set(string $key, mixed $value, null|int|DateInterval $ttl = null): bool
    {
        $this->values[$key] = $value;
        $this->ttls[$key] = $ttl;
        return true;
    }

    public function ttl(string $key): null|int|DateInterval
    {
        return $this->ttls[$key] ?? null;
    }

    public function delete(string $key): bool
    {
        unset($this->values[$key]);
        return true;
    }

    public function clear(): bool
    {
        $this->values = [];
        return true;
    }

    public function getMultiple(iterable $keys, mixed $default = null): iterable
    {
        $result = [];
        foreach ($keys as $key) {
            $result[$key] = $this->get($key, $default);
        }
        return $result;
    }

    public function setMultiple(iterable $values, null|int|DateInterval $ttl = null): bool
    {
        foreach ($values as $key => $value) {
            $this->set($key, $value, $ttl);
        }
        return true;
    }

    public function deleteMultiple(iterable $keys): bool
    {
        foreach ($keys as $key) {
            $this->delete($key);
        }
        return true;
    }

    public function has(string $key): bool
    {
        return array_key_exists($key, $this->values);
    }
}
